/* Blog behaviour. Pages are static HTML generated by Jekyll; this only adds progressive enhancements. */
(function () {
  'use strict';
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const goTo = (el, block = 'start') => el && el.scrollIntoView({ behavior: reduceMotion.matches ? 'auto' : 'smooth', block });

  /* ---------- Relative dates ("3 days ago") ---------- */
  $$('time.ago').forEach(t => {
    const days = Math.max(0, Math.round((Date.now() - new Date(t.dateTime)) / 864e5));
    if (!Number.isNaN(days)) t.textContent = days === 0 ? 'today' : days === 1 ? 'yesterday' : `${days} days ago`;
  });

  /* ---------- Toast ---------- */
  const toast = $('.toast');
  let toastTimer;
  const say = msg => {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2000);
  };

  /* ---------- Tags page: show a single tag when the URL has #tag ---------- */
  const tagSections = $$('.tagsec');
  if (tagSections.length) {
    const filter = $('[data-filter]');
    const applyFilter = () => {
      const id = decodeURIComponent(location.hash.slice(1));
      const match = tagSections.find(s => s.id === id);
      tagSections.forEach(s => { s.hidden = !!match && s !== match; });
      $$('.tagshead .chip').forEach(c => c.classList.toggle('on', !!match && c.dataset.tag === id));
      if (filter) {
        filter.hidden = !match;
        if (match) filter.querySelector('b').textContent = match.querySelector('.sect').firstChild.textContent.trim();
      }
      if (match) scrollTo(0, 0);
    };
    $$('.tagshead .chip').forEach(c => c.addEventListener('click', e => {
      if (c.classList.contains('on')) { e.preventDefault(); history.replaceState(null, '', location.pathname); applyFilter(); }
    }));
    addEventListener('hashchange', applyFilter);
    applyFilter();
  }

  /* ---------- Home: the tags tile shows only whole chips, packed into its rows, and a "+N" link to the rest ---------- */
  const tagTile = $('.bento .tile.tags');
  if (tagTile) {
    const box = $('.chips', tagTile);
    const chips = $$('.chip', box);
    const rest = document.createElement('a');
    rest.className = 'chip rest';
    rest.href = '/blog/tags/';
    const width = el => el.getBoundingClientRect().width;
    const fitTags = () => {
      // Back to the natural flow: every chip, most used first.
      rest.remove();
      chips.forEach(c => { c.hidden = false; box.appendChild(c); });
      $$('.crow', box).forEach(r => r.remove());
      box.classList.remove('packed');
      const limit = tagTile.getBoundingClientRect().bottom - parseFloat(getComputedStyle(tagTile).paddingBottom) + 0.5;
      if (chips.every(c => c.getBoundingClientRect().bottom <= limit)) return;
      // They don't all fit: each chip, in order, goes into the first row with room for it (filling the gaps);
      // the ones that fit nowhere are hidden and "+N" closes the last row.
      const style = getComputedStyle(box);
      const gap = parseFloat(style.columnGap) || 0, rowGap = parseFloat(style.rowGap) || 0;
      const room = box.clientWidth + 0.5;
      const rows = Array.from({ length: Math.max(1, Math.floor((limit - box.getBoundingClientRect().top + rowGap) / (chips[0].offsetHeight + rowGap))) }, () => []);
      const fitsIn = (row, w) => row.reduce((s, c) => s + width(c) + gap, 0) + w <= room;
      const hidden = [];
      chips.forEach(c => (rows.find(row => fitsIn(row, width(c))) || hidden).push(c));
      if (hidden.length) {
        const last = rows[rows.length - 1];
        box.appendChild(rest);
        for (;;) {
          rest.textContent = `+${hidden.length}`;
          if (fitsIn(last, width(rest)) || !last.length) break;
          hidden.push(last.pop());
        }
        last.push(rest);
        rest.title = `${hidden.length} more tag${hidden.length === 1 ? '' : 's'}`;
        rest.setAttribute('aria-label', rest.title);
      }
      hidden.forEach(c => { c.hidden = true; });
      box.classList.add('packed');
      rows.filter(r => r.length).forEach(r => { const row = document.createElement('div'); row.className = 'crow'; row.append(...r); box.appendChild(row); });
    };
    let fitQueued = false;
    const queueFit = () => { if (!fitQueued) { fitQueued = true; requestAnimationFrame(() => { fitQueued = false; fitTags(); }); } };
    fitTags();
    // Web fonts change the chips' width: fit again once they (and the page) have loaded.
    if (document.fonts) { document.fonts.ready.then(queueFit); document.fonts.addEventListener('loadingdone', queueFit); }
    addEventListener('load', queueFit);
    addEventListener('resize', queueFit, { passive: true });
  }

  /* ---------- Post page ---------- */
  const art = $('#art');
  if (!art) return;
  const share = { url: art.dataset.url, title: art.dataset.title, text: art.dataset.text };
  const canShare = typeof navigator.share === 'function';

  // Language label on code blocks (kramdown + Rouge output).
  $$('.body div.highlighter-rouge, .body figure.highlight').forEach(box => {
    const m = box.className.match(/language-([\w+#-]+)/);
    const code = box.querySelector('code[data-lang]');
    const lang = code ? code.dataset.lang : m && m[1];
    const pre = box.querySelector('pre');
    if (pre && lang && lang !== 'plaintext') pre.dataset.lang = lang;
  });

  // Wide tables scroll horizontally on small screens instead of overflowing the page.
  $$('.body table').forEach(t => {
    const w = document.createElement('div');
    w.className = 'tw';
    t.replaceWith(w);
    w.appendChild(t);
  });

  // Share: copy link, native share sheet, and fallbacks.
  async function copyLink(btn) {
    try { await navigator.clipboard.writeText(share.url); } catch (e) {
      const t = document.createElement('textarea');
      t.value = share.url; t.setAttribute('readonly', ''); t.style.position = 'fixed'; t.style.opacity = '0';
      document.body.appendChild(t); t.select();
      const ok = document.execCommand('copy'); t.remove();
      if (!ok) return say('Could not copy the link');
    }
    say('✓ Link copied to clipboard');
    if (!btn) return;
    const svg = btn.querySelector('svg');
    if (!btn.dataset.icon) btn.dataset.icon = svg.outerHTML;
    svg.outerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>';
    btn.classList.add('ok');
    clearTimeout(btn._t);
    btn._t = setTimeout(() => { btn.querySelector('svg').outerHTML = btn.dataset.icon; btn.classList.remove('ok'); }, 2000);
  }
  const nativeShare = () => navigator.share({ title: share.title, text: share.text, url: share.url }).catch(() => {});
  if (canShare) $$('[data-native]').forEach(b => { b.hidden = false; });
  document.addEventListener('click', e => {
    const b = e.target.closest('[data-copy], [data-native], [data-native-or-scroll], [data-share-any]');
    if (!b) return;
    if (b.matches('[data-copy]')) { e.preventDefault(); copyLink(b); return; }
    if (b.matches('[data-native]')) { e.preventDefault(); nativeShare(); return; }
    if (b.matches('[data-share-any]')) { e.preventDefault(); canShare ? nativeShare() : copyLink(); return; }
    e.preventDefault();
    canShare ? nativeShare() : goTo($('#share'), 'center');
  });

  // Table of contents from the post's h2 headings, plus a link to the comments.
  const hs = $$('.body h2', art);
  hs.forEach((h, i) => { if (!h.id) h.id = 'section-' + (i + 1); });
  const comments = $('#comments');
  const toc = $('#toc');
  const lst = $('.lst', toc);
  lst.insertAdjacentHTML('afterbegin', hs.map(h => {
    const a = document.createElement('a');
    a.href = '#' + h.id; a.dataset.to = h.id; a.textContent = h.textContent;
    return a.outerHTML;
  }).join(''));
  $$('a', toc).forEach(a => a.addEventListener('click', e => {
    e.preventDefault();
    const el = document.getElementById(a.dataset.to);
    goTo(el);
    history.replaceState(null, '', '#' + a.dataset.to);
  }));
  const marks = [...hs, comments];

  // Reading progress (sidebar ring + mobile pill) and the active section in the table of contents.
  const ahead = $('#ahead'), mprog = $('#mprog');
  const fgs = $$('.ring .fg');
  const pc = $('.prog .pc'), lt = $('.prog .lt'), ls = $('.prog .ls');
  const mp = $('.mp', mprog), ml = $('.ml', mprog);
  const minutes = parseInt(art.dataset.minutes, 10) || 1;
  let ticking = false, lastOn = null;
  function update() {
    ticking = false;
    const r = art.getBoundingClientRect();
    // Guard: if the post is shorter than half the screen the denominator would be 0 or negative.
    const span = Math.max(1, r.height - innerHeight * 0.5);
    const f = Math.min(1, Math.max(0, (innerHeight * 0.35 - r.top) / span));
    const pct = Math.round(f * 100) + '%';
    fgs.forEach(c => { c.style.strokeDashoffset = 264 * (1 - f); });
    if (pc) pc.textContent = pct;
    mp.textContent = pct;
    const rem = Math.ceil(minutes * (1 - f));
    const done = f >= 0.99, started = f > 0;
    lt.textContent = done ? 'Done! 🎉' : started ? `${rem} min left` : `${minutes} min read`;
    ls.textContent = done ? 'Thanks for reading' : started ? `${pct} read` : 'Scroll to start';
    ml.textContent = done ? 'Done! 🎉' : `${rem} min left`;
    mprog.classList.toggle('show', ahead.getBoundingClientRect().bottom < 0);
    let cur = marks[0];
    marks.forEach(h => { if (h.getBoundingClientRect().top < innerHeight * 0.35) cur = h; });
    if (innerHeight + scrollY >= document.documentElement.scrollHeight - 4) cur = marks[marks.length - 1];
    if (cur !== lastOn) {
      lastOn = cur;
      $$('a', toc).forEach(a => a.classList.toggle('on', a.dataset.to === cur.id));
      // Keep the active entry visible inside the (scrollable) table of contents without moving the page.
      const on = $('a.on', lst);
      if (on && lst.scrollHeight > lst.clientHeight) {
        const top = on.offsetTop - lst.offsetTop;
        if (top < lst.scrollTop || top + on.offsetHeight > lst.scrollTop + lst.clientHeight) lst.scrollTop = top - lst.clientHeight / 2;
      }
    }
  }
  const onScroll = () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } };
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', onScroll, { passive: true });
  update();

  // Comments (giscus). Loaded only when the reader gets close, so nobody contacts giscus.app unless they scroll there.
  const box = $('.giscus', comments);
  const giscusTheme = () => (window.Theme && Theme.get() === 'dark') ? 'transparent_dark' : 'noborder_light';
  function loadGiscus() {
    const s = document.createElement('script');
    s.src = 'https://giscus.app/client.js';
    const d = box.dataset;
    Object.entries({
      repo: d.repo, 'repo-id': d.repoId, category: d.category, 'category-id': d.categoryId,
      mapping: 'specific', term: d.term, strict: '1', 'reactions-enabled': '1', 'emit-metadata': '1',
      'input-position': 'top', theme: giscusTheme(), lang: 'en', loading: 'lazy'
    }).forEach(([k, v]) => s.setAttribute('data-' + k, v));
    s.crossOrigin = 'anonymous';
    s.async = true;
    box.appendChild(s);
  }
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver(entries => {
      if (entries.some(en => en.isIntersecting)) { io.disconnect(); loadGiscus(); }
    }, { rootMargin: '800px 0px' });
    io.observe(box);
  } else {
    loadGiscus();
  }
  new MutationObserver(() => {
    const f = $('iframe.giscus-frame');
    if (f) f.contentWindow.postMessage({ giscus: { setConfig: { theme: giscusTheme() } } }, 'https://giscus.app');
  }).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
  // Comment count next to "Comments" in the table of contents.
  addEventListener('message', e => {
    if (e.origin !== 'https://giscus.app') return;
    const d = e.data && e.data.giscus && e.data.giscus.discussion;
    const cc = $('.cc', toc);
    if (d && cc) { const n = d.totalCommentCount + d.totalReplyCount; cc.textContent = n ? ` · ${n}` : ''; }
  });
})();
